const config = {
  driveId: 'b!C2yhEx592Ei36yvay6U9n6Opn9Rg7v1LnJCWDZ9ZCSJEbUEViC4mS52f5_kGkuq_',
  driveName: 'Documents (Shared Documents) der Untersite Schulungen',
  siteUrl: 'https://rwgrheinland.sharepoint.com/sites/rwgintranet/Schulungen',

  // ============================================================
  // PRODUKTIVBETRIEB seit 30.08.2026
  //
  // Jeder in der Bibliothek vorhandene Dateityp ist einzeln belegt:
  //   pdf   110458  174 Woerter, mistral-ocr-latest
  //   docx  110460  158 Woerter, ueber format=pdf gewandelt
  //   pptx  110462  1360 Woerter, 9 Textstuecke UND 20 Bilder
  //   txt   110432  semantic
  //   xls   110432  2555 Woerter, relational
  //   xlsx  110430  zwoelf Blaetter, 1930 Zeilen, 35077 Woerter
  //
  //   csv und xlsm: in der Bibliothek liegt keine Datei davon.
  //   Die Wege sind gebaut, aber nicht an echten Daten belegt.
  // ============================================================
  aktiveTypen: ['pdf', 'docx', 'doc', 'pptx', 'ppt', 'txt', 'csv', 'xlsx', 'xls', 'xlsm'],

  // Obergrenze je Typ und Lauf. Beim stuendlichen Takt kommen selten
  // mehr Aenderungen zusammen; die Grenze ist eine Bremse gegen
  // Ausreisser, keine Auswahl.
  maxJeTyp: 25,

  // Namensfilter fuer gezielte Tests. Im Betrieb leer.
  nurDatei: '',

  verarbeiten: true,
  ingestAufrufen: true,
  zustandSchreiben: true,
  loeschungenMelden: true,

  // Erzwingt einen Vollabruf, ohne den gespeicherten Anker zu
  // loeschen. Nur fuer eine Erstbefuellung des Altbestands noetig:
  // Im Normalbetrieb sieht der Flow nur Aenderungen, und eine Datei
  // die seit Monaten unveraendert liegt taucht nicht mehr auf.
  ankerIgnorieren: false,

  audience: 'public',
  maxDateiMb: 40,
  maxZeilenJeBlatt: 5000
};

// Word und PowerPoint gehen ueber die PDF-Wandlung von Graph in
// dieselbe OCR-Strecke wie die PDFs. Bei PowerPoint zahlt sich das
// besonders aus: Mistral erfasst dann auch die Folienbilder.
config.ueberPdf = ['docx', 'doc', 'pptx', 'ppt'];

// Arbeitsmappen werden ueber die Workbook-API gelesen, weil der
// Extract-Node nur ein Blatt kennt und die uebrigen lautlos weglaesst.
config.ueberWorkbook = ['xlsx', 'xlsm'];

return [{ json: { _config: config } }];

const cfg = $('Config').first().json._config;
const aktiv = new Set(cfg.aktiveTypen.map(t => String(t).toLowerCase()));
const ueberPdf = new Set((cfg.ueberPdf || []).map(t => String(t).toLowerCase()));
const ueberWorkbook = new Set((cfg.ueberWorkbook || []).map(t => String(t).toLowerCase()));
const maxBytes = Number(cfg.maxDateiMb || 40) * 1048576;
const nurDatei = String(cfg.nurDatei || '').trim().toLowerCase();

let items = [];
let deltaLink = null;
for (const s of $input.all()) {
  const b = s.json || {};
  for (const v of (b.value || [])) items.push(v);
  if (b['@odata.deltaLink']) deltaLink = b['@odata.deltaLink'];
}

function endung(name) {
  const t = String(name || '').split('.');
  return t.length > 1 ? t.pop().toLowerCase() : '';
}
function ohneEndung(name) {
  const s = String(name || '');
  const i = s.lastIndexOf('.');
  return i > 0 ? s.slice(0, i) : s;
}
function pfadVon(it) {
  const p = (it.parentReference && it.parentReference.path) || '';
  const rein = p.replace(/^\/drives?\/[^/]+\/root:?/, '');
  return (rein ? decodeURIComponent(rein) : '') + '/' + it.name;
}
// Der oberste Ordner unter der Bibliothekswurzel taugt als Bereich.
// Power Automate liefert department heute frei Haus; ohne Ersatz
// verloere der Agent das Feld beim Umstieg.
function bereichVon(pfad) {
  const teile = String(pfad || '').split('/').filter(Boolean);
  return teile.length > 1 ? teile[0] : null;
}

// Delta meldet entfernte Eintraege mit deleted-Vermerk und ohne
// Namen. Ohne Weitergabe blieben ihre Chunks stehen und der Agent
// antwortete aus Dokumenten, die es nicht mehr gibt.
const liste = [];
const dateien = [];
let geloescht = 0;

for (const it of items) {
  if (it.deleted) {
    geloescht++;
    if (cfg.loeschungenMelden) {
      liste.push({ aktion: 'loeschen', item_id: it.id, filename: it.name || null, drive_id: cfg.driveId });
    }
    continue;
  }
  if (it.file) dateien.push(it);
}

const zaehler = {};
const gesehen = {};
const uebersprungen = { falscher_typ: 0, zu_gross: 0, limit_erreicht: 0, namensfilter: 0 };

for (const it of dateien) {
  const ext = endung(it.name);
  gesehen[ext] = (gesehen[ext] || 0) + 1;
  if (!aktiv.has(ext)) { uebersprungen.falscher_typ++; continue; }
  if (nurDatei && String(it.name || '').toLowerCase().indexOf(nurDatei) === -1) { uebersprungen.namensfilter++; continue; }
  if (Number(it.size || 0) > maxBytes) { uebersprungen.zu_gross++; continue; }
  zaehler[ext] = (zaehler[ext] || 0) + 1;
  if (zaehler[ext] > Number(cfg.maxJeTyp || 1)) { uebersprungen.limit_erreicht++; continue; }

  const pfad = pfadVon(it);
  const erst = (it.createdBy && it.createdBy.user) || {};
  const letzt = (it.lastModifiedBy && it.lastModifiedBy.user) || {};
  const istMappe = ueberWorkbook.has(ext);

  liste.push({
    aktion: istMappe ? 'tabelle' : 'datei',
    item_id: it.id,
    drive_id: cfg.driveId,
    filename: it.name,
    uebergabe_name: istMappe ? (ohneEndung(it.name) + ' (' + ext + ', alle Blaetter).csv') : it.name,
    endung: ext,
    als_pdf: ueberPdf.has(ext),
    bytes: Number(it.size || 0),
    file_path: pfad,
    department: bereichVon(pfad),
    sharepoint_url: it.webUrl || null,
    author_name: erst.displayName || null,
    author_email: erst.email || null,
    last_modified_by: letzt.displayName || null,
    created_at_sp: it.createdDateTime || null,
    last_modified_sp: it.lastModifiedDateTime || null,
    etag: it.eTag || null,
    audience: cfg.audience
  });
}

const formate = Object.keys(gesehen).sort((a, b) => gesehen[b] - gesehen[a]).map(e => e + ':' + gesehen[e]);

return [{ json: {
  _lauf: {
    items_im_delta: items.length,
    dateien: dateien.length,
    geloescht,
    geloescht_gemeldet: cfg.loeschungenMelden ? geloescht : 0,
    formate_gesehen: formate,
    aktive_typen: cfg.aktiveTypen,
    max_je_typ: cfg.maxJeTyp,
    namensfilter: cfg.nurDatei || null,
    einzulesen: liste.filter(a => a.aktion !== 'loeschen').length,
    aufgaben_gesamt: liste.length,
    uebersprungen,
    delta_link: deltaLink,
    delta_link_erhalten: !!deltaLink,
    vollabruf: !$('Zustand laden').first().json.delta_link
  },
  aufgaben: liste
} }];

const cfg = $('Config').first().json._config;
const lauf = $('Aufgaben bestimmen').first().json._lauf;
return [{ json: {
  drive_id: cfg.driveId,
  drive_name: cfg.driveName,
  delta_link: lauf.delta_link,
  letzte_items: lauf.items_im_delta,
  letzte_uebergeben: lauf.aufgaben_gesamt
} }];

const cfg = $('Config').first().json._config;
const lauf = $('Aufgaben bestimmen').first().json._lauf || {};
const aufgaben = $('Aufgaben bestimmen').first().json.aufgaben || [];

// ============================================================
// ALLE SCHLEIFENDURCHLAEUFE EINSAMMELN
//
// In einer splitInBatches-Schleife liefert $('Node').all() nur den
// LETZTEN Durchlauf. Bei vier Dokumenten sah die Zusammenfassung
// deshalb nur das vierte - die drei davor fehlten lautlos.
// ============================================================
function sammle(name) {
  const raus = [];
  for (let i = 0; i < 1000; i++) {
    let items;
    try { items = $(name).all(0, i); } catch (e) { break; }
    if (!items || !items.length) break;
    for (const it of items) raus.push(it.json || {});
  }
  return raus;
}

const ergebnisse = sammle('RAG-Ingest');
const fehler = ergebnisse.filter(j => j.error).map(j => String(j.error.message || j.error).slice(0, 160));
const mappen = sammle('Tabelle als CSV bauen');
const dateien = sammle('Uebergabe Datei');
const nichtLesbar = dateien.concat(mappen).filter(j => j._fehler);

return [{ json: {
  bibliothek: cfg.driveName,
  modus: !cfg.verarbeiten ? 'Trockenlauf - nur gesichtet'
       : !cfg.ingestAufrufen ? 'Verarbeitet, nicht uebergeben'
       : 'An den Ingest uebergeben',
  aktive_typen: lauf.aktive_typen,
  max_je_typ: lauf.max_je_typ,
  namensfilter: lauf.namensfilter,
  vollabruf: lauf.vollabruf,
  items_im_delta: lauf.items_im_delta,
  dateien_gesamt: lauf.dateien,
  formate_gesehen: lauf.formate_gesehen,
  einzulesen: lauf.einzulesen,
  geloescht_im_delta: lauf.geloescht,
  loeschungen_gemeldet: lauf.geloescht_gemeldet,
  uebersprungen: lauf.uebersprungen,
  verarbeitet_dateien: dateien.filter(j => !j._fehler).length,
  verarbeitet_mappen: mappen.filter(j => !j._fehler).length,
  an_ingest_uebergeben: ergebnisse.length - fehler.length,
  ingest_fehler: fehler,
  nicht_lesbar: nichtLesbar.map(j => (j.filename || '?') + ': ' + j._fehler),
  mappen: mappen.filter(t => !t._fehler).map(t => ({
    datei: t.filename,
    als_tabelle: t._blaetter_tabelle,
    als_text: t._blaetter_text,
    zeilen_tabelle: t._zeilen_tabelle,
    zeilen_text: t._zeilen_text,
    spalten: t._spaltennamen,
    hinweise: t._hinweise
  })),
  delta_link_erhalten: lauf.delta_link_erhalten,
  anker_geschrieben: !!cfg.zustandSchreiben && !!lauf.delta_link_erhalten,
  aufgabenliste: aufgaben.map(a => a.aktion + ' | ' + (a.endung || '-') + ' | ' + (a.file_path || a.item_id))
} }];

// Genau die Felder, die Power Automate heute in den Webhook schreibt.
const cfg = $('Config').first().json._config;
const a = $('Je Aufgabe').first().json;
const b64 = $input.first().json.fileBase64;

if (!b64) {
  return [{ json: { _fehler: 'KEIN_INHALT', filename: a.filename, aktion: a.aktion } }];
}

return [{ json: {
  operation: 'UPDATE',
  file_id: a.item_id,
  filename: a.uebergabe_name || a.filename,
  fileBase64: b64,
  filepath: a.file_path,
  site_url: cfg.siteUrl,
  sharepoint_url: a.sharepoint_url,
  drive_id: a.drive_id,
  author_name: a.author_name,
  author_email: a.author_email,
  last_modified_by: a.last_modified_by,
  created_at_sp: a.created_at_sp,
  last_modified_sp: a.last_modified_sp,
  department: a.department,
  document_version: a.etag,
  language: 'de',
  audience: a.audience,
  quelle: 'delta-leser',
  original_extension: a.endung,
  ueber_pdf_gewandelt: !!a.als_pdf
} }];

// Jedes Blatt wird ein eigenes Item, damit der folgende Abruf je
// Blatt einmal laeuft. Ausgeblendete Blaetter bleiben aussen vor -
// sie sind bewusst versteckt.
const antwort = $input.first().json || {};
const a = $('Je Aufgabe').first().json;

if (antwort.error || !antwort.value) {
  const grund = antwort.error ? String(antwort.error.message || antwort.error).slice(0, 160) : 'KEINE_ANTWORT';
  return [{ json: Object.assign({}, a, { blatt: null, blatt_fehler: grund, blaetter_gesamt: 0, blatt_index: 0 }) }];
}

const alle = antwort.value || [];
const sichtbar = alle.filter(w => !w.visibility || w.visibility === 'Visible');

if (!sichtbar.length) {
  return [{ json: Object.assign({}, a, { blatt: null, blatt_fehler: 'KEINE_SICHTBAREN_BLAETTER', blaetter_gesamt: 0, blatt_index: 0 }) }];
}

return sichtbar
  .sort((x, y) => Number(x.position || 0) - Number(y.position || 0))
  .map((w, i) => ({ json: Object.assign({}, a, {
    blatt: w.name,
    blatt_index: i,
    blaetter_gesamt: sichtbar.length,
    blaetter_alle: alle.length,
    blatt_fehler: null
  }) }));

// ============================================================
// ARBEITSMAPPE AUFBEREITEN
//
// Nicht jedes Blatt einer Arbeitsmappe ist eine Tabelle. Es gibt
// Deckblaetter, Notizen, ausgefuellte Formulare und Layouts. Wer
// dort blind die erste Zeile als Kopfzeile nimmt, erzeugt Unsinn:
// aus einer Ueberschrift wird ein Spaltenname und aus dem Text
// darunter ein Datensatz.
//
// Und selbst echte Tabellen fangen selten in Zeile 1 an. Ueber der
// Kopfzeile stehen Titel, Stand-Angaben oder Leerzeilen. Deshalb
// wird die Kopfzeile in den ersten Zeilen gesucht statt angenommen.
//
// Blaetter, die als Tabelle durchgehen, kommen mit ihren echten
// Spalten. Alles andere wird als Text uebernommen - Zeile fuer Zeile
// unter den Spalten Blatt, Zeile und Inhalt. Beides landet in
// derselben CSV, damit eine Datei ein Dokument bleibt und eine
// spaetere Loeschung sie vollstaendig trifft.
// ============================================================
const cfg = $('Config').first().json._config;
const a = $('Je Aufgabe').first().json;
const maxZeilen = Number(cfg.maxZeilenJeBlatt || 5000);
const SUCHTIEFE = 8;

function text(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}
function istZahl(v) {
  const s = text(v);
  return s !== '' && !isNaN(Number(s.replace(/\./g, '').replace(',', '.')));
}

// Bewertet, wie gut eine Zeile als Kopfzeile taugt. Null heisst
// ungeeignet. Je hoeher, desto besser.
function kopfGuete(werte, i) {
  const zeile = werte[i] || [];
  const gefuellt = zeile.filter(c => text(c) !== '');
  if (gefuellt.length < 2) return 0;

  // Eine Kopfzeile besteht aus Bezeichnungen, nicht aus Messwerten.
  const zahlanteil = gefuellt.filter(istZahl).length / gefuellt.length;
  if (zahlanteil > 0.5) return 0;

  // Spaltennamen wiederholen sich nicht.
  const eindeutig = new Set(gefuellt.map(c => text(c).toLowerCase())).size;
  if (eindeutig < gefuellt.length * 0.8) return 0;

  // Ein ganzer Absatz in einer Zelle ist keine Spaltenbezeichnung.
  if (gefuellt.filter(c => text(c).length > 120).length) return 0;

  // Unter der Kopfzeile muessen Daten stehen, die die Spalten fuellen.
  const probe = werte.slice(i + 1, i + 21);
  if (probe.length < 2) return 0;
  const schnitt = probe.reduce((s, z) => s + z.filter(c => text(c) !== '').length, 0) / probe.length;
  const fuellgrad = schnitt / gefuellt.length;
  if (fuellgrad < 0.3) return 0;

  // Mehr Spalten und besserer Fuellgrad sind besser. Fruehe Zeilen
  // gewinnen bei Gleichstand, damit ein Titel ueber der Tabelle die
  // Wahl nicht verschiebt.
  return gefuellt.length * Math.min(fuellgrad, 1) * 100 - i;
}

const eingang = $input.all();
const tabellen = [];
const notizen = [];
const hinweise = [];

for (let i = 0; i < eingang.length; i++) {
  const j = eingang[i].json || {};
  const meta = $('Blaetter auffaechern').all()[i];
  const name = (meta && meta.json.blatt) || j.blatt || ('Blatt ' + (i + 1));

  if (meta && meta.json.blatt_fehler) { hinweise.push(name + ': ' + meta.json.blatt_fehler); continue; }
  if (j.error) { hinweise.push(name + ': ' + String(j.error.message || j.error).slice(0, 120)); continue; }

  const alle = Array.isArray(j.values) ? j.values : [];
  const werte = alle.filter(z => z.some(c => text(c) !== ''));
  if (!werte.length) { hinweise.push(name + ': leer'); continue; }

  if (werte.length > maxZeilen + 1) {
    hinweise.push(name + ': auf ' + maxZeilen + ' von ' + (werte.length - 1) + ' Zeilen begrenzt');
  }

  // Kopfzeile suchen statt annehmen.
  let besteZeile = -1;
  let besteGuete = 0;
  for (let k = 0; k < Math.min(SUCHTIEFE, werte.length - 2); k++) {
    const g = kopfGuete(werte, k);
    if (g > besteGuete) { besteGuete = g; besteZeile = k; }
  }

  if (besteZeile >= 0) {
    const kopf = werte[besteZeile].map((c, k) => text(c) || ('Spalte ' + (k + 1)));
    // Was ueber der Kopfzeile steht, ist meist ein Titel. Er geht
    // nicht verloren, sondern kommt als Textzeile mit.
    const davor = werte.slice(0, besteZeile)
      .map((z, k) => ({ nr: k + 1, inhalt: z.map(text).filter(Boolean).join('  |  ') }))
      .filter(z => z.inhalt);
    if (davor.length) notizen.push({ name: name + ' (Kopfbereich)', zeilen: davor });
    if (besteZeile > 0) hinweise.push(name + ': Kopfzeile in Zeile ' + (besteZeile + 1) + ' gefunden');

    tabellen.push({ name, kopf, zeilen: werte.slice(besteZeile + 1, besteZeile + 1 + maxZeilen) });
  } else {
    const zeilen = werte.slice(0, maxZeilen).map((z, k) => ({
      nr: k + 1,
      inhalt: z.map(text).filter(Boolean).join('  |  ')
    })).filter(z => z.inhalt);
    if (zeilen.length) {
      notizen.push({ name, zeilen });
      hinweise.push(name + ': als Text uebernommen, keine Tabellenstruktur erkannt');
    }
  }
}

if (!tabellen.length && !notizen.length) {
  return [{ json: { _fehler: 'KEINE_BLATTDATEN', filename: a.filename, hinweise } }];
}

const spalten = [];
const bekannt = new Set();
for (const b of tabellen) {
  for (const s of b.kopf) { if (!bekannt.has(s)) { bekannt.add(s); spalten.push(s); } }
}
if (notizen.length) {
  for (const s of ['Zeile', 'Inhalt']) { if (!bekannt.has(s)) { bekannt.add(s); spalten.push(s); } }
}

function feld(v) {
  const t = v === null || v === undefined ? '' : String(v);
  return /[",\n\r]/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t;
}

const ausgabe = [['Blatt'].concat(spalten).map(feld).join(',')];
let zeilenTabelle = 0;
let zeilenText = 0;

for (const b of tabellen) {
  const nachSpalte = {};
  b.kopf.forEach((s, k) => { if (nachSpalte[s] === undefined) nachSpalte[s] = k; });
  for (const z of b.zeilen) {
    if (!z.some(c => text(c) !== '')) continue;
    const reihe = [b.name].concat(spalten.map(s => {
      const k = nachSpalte[s];
      return k === undefined ? '' : z[k];
    }));
    ausgabe.push(reihe.map(feld).join(','));
    zeilenTabelle++;
  }
}

for (const b of notizen) {
  for (const z of b.zeilen) {
    const reihe = [b.name].concat(spalten.map(s => {
      if (s === 'Zeile') return z.nr;
      if (s === 'Inhalt') return z.inhalt;
      return '';
    }));
    ausgabe.push(reihe.map(feld).join(','));
    zeilenText++;
  }
}

const csv = ausgabe.join('\n');

// Der Name sagt, was drin ist. Eine reine Notizmappe soll im RAG
// nicht als Tabelle auftreten.
const art = tabellen.length && notizen.length ? 'Tabellen und Text'
          : tabellen.length ? 'alle Blaetter'
          : 'als Text';
const basis = String(a.uebergabe_name || '').replace(/ \([^)]*\)\.csv$/, '');

return [{ json: {
  operation: 'UPDATE',
  file_id: a.item_id,
  filename: basis + ' (' + a.endung + ', ' + art + ').csv',
  fileBase64: Buffer.from(csv, 'utf8').toString('base64'),
  filepath: a.file_path,
  site_url: cfg.siteUrl,
  sharepoint_url: a.sharepoint_url,
  drive_id: a.drive_id,
  author_name: a.author_name,
  author_email: a.author_email,
  last_modified_by: a.last_modified_by,
  created_at_sp: a.created_at_sp,
  last_modified_sp: a.last_modified_sp,
  department: a.department,
  document_version: a.etag,
  language: 'de',
  audience: a.audience,
  quelle: 'delta-leser',
  original_extension: a.endung,
  ueber_pdf_gewandelt: false,
  _blaetter_tabelle: tabellen.map(b => b.name),
  _blaetter_text: notizen.map(b => b.name),
  _blaetter_anzahl: tabellen.length + notizen.length,
  _zeilen: zeilenTabelle + zeilenText,
  _zeilen_tabelle: zeilenTabelle,
  _zeilen_text: zeilenText,
  _spalten: spalten.length,
  _spaltennamen: spalten.slice(0, 12),
  _hinweise: hinweise
} }];

// Der Ingest hat einen eigenen Loeschzweig. Er braucht nur die
// Kennung und die Absicht - kein Dateiinhalt, den es ja auch
// nicht mehr gibt.
const a = $input.first().json;
return [{ json: {
  operation: 'DELETE',
  deleted: true,
  file_id: a.item_id,
  filename: a.filename,
  drive_id: a.drive_id,
  quelle: 'delta-leser'
} }];

// Liegt dieselbe Datei bereits unter einer fremden Kennung im RAG?
// Beim Uebergang von Power Automate ist das der Regelfall: Dort
// trugen die Dokumente Kennungen der Form RWGID-..., hier ist es die
// Graph-Item-ID.
//
// Gesucht wird ueber den Dateinamen, nicht ueber den Pfad - Power
// Automate schreibt ihn anders als der Delta-Leser, ein Abgleich
// waere unzuverlaessig.
//
// Geloescht wird nur bei GENAU EINEM fremden Treffer. Gibt es
// mehrere Dateien gleichen Namens in verschiedenen Ordnern, laesst
// sich nicht sicher sagen welche gemeint ist - dann bleibt alles
// stehen und die Doublette wird gemeldet.
const a = $('Je Aufgabe').first().json;
const antwort = $input.first().json;
const treffer = Array.isArray(antwort) ? antwort : (antwort && antwort.doc_id ? [antwort] : []);

const eigene = String(a.item_id || '');
const fremd = treffer.filter(t => String(t.doc_id || '') && String(t.doc_id) !== eigene);

const eindeutig = fremd.length === 1;

return [{ json: Object.assign({}, a, {
  alt_doc_id: eindeutig ? String(fremd[0].doc_id) : null,
